"use strict";const data=[{title:"⭐ Stew",sub:"Build Tool | Static Site Generator",desc:"Purpose-built for developers who value simplicity and control, this template combines raw HTML and CSS with the reliability of type-safe JavaScript. It delivers a clean, modern development experience without the overhead of large frameworks, featuring a streamlined build pipeline, optimized output, and an intuitive project structure. The result is a lightweight foundation that stays true to the web platform while providing the tools needed to build fast, maintainable, and scalable websites.\n\n Made in 2026",img:"images/projects/stew.webp",link:"https://ichimakikasura.github.io/Stew/"},{title:"⭐ IchiProtoTech",sub:"Embedded System Service | Freelance Service",desc:"ichiProtoTech is a specialized freelance development service that provides affordable, budget-friendly hardware and Internet of Things (IoT) prototyping solutions tailored specifically for student projects and academic requirements. The platform focuses on building functional, low-cost working models using popular microcontrollers like Arduino, ESP32, and Raspberry Pi to help learners meet school defense and thesis objectives. By combining technical expertise in embedded systems with support services like basic programming tutorials and computer repair, ichiProtoTech bridges the gap between complex engineering concepts and practical, accessible implementation for beginners and DIY enthusiasts.\n\n Made in 2026",img:"images/projects/ichiprototech.webp",link:"https://ichiprototech.com/"},{title:"⭐ MeguClock",sub:"Embedded System Hardware | C/C++",desc:'MeguClock is a customized digital clock project built on the Arduino Uno/Nano platforms that features a blend of functional hardware and playful, "goofy" software elements. Leveraging a 1.8-inch ST7735 display and a DS3231 real-time clock module, the device includes hardware-integrated alarms with hardcoded sound bites, a customizable color interface, and a randomized message ticker that updates every ten seconds. The project is notable for its use of highly optimized, independent libraries for the display and RTC, which have been stripped of unnecessary code to maximize the limited memory of standard microcontrollers. With a focus on DIY accessibility, it utilizes a simple two-button control scheme and a passive buzzer for audio alerts, providing a modular foundation for hobbyists to experiment with embedded C++ and hardware interfacing.\n\n Made in 2026',img:"images/projects/meguclock.webp",link:"https://github.com/IchimakiKasura/MeguClock"},{title:"⭐ Facial Integrated System Technology",sub:"School project | Facial Recognition Attendance System | Node.js",desc:"Facial Integrated System Technology is a comprehensive full-stack Node.js application that automates attendance tracking through advanced facial recognition and school policy integration. This high-performance prototype leverages the Face-API library to provide simultaneous detection for up to five individuals using diverse hardware inputs, including USB webcams and Raspberry Pi-powered IP cameras. The system is engineered with a versatile triple-interface architecture—featuring dedicated portals for public, admin, and mobile users—while ensuring data accessibility by exporting real-time attendance logs directly to Excel formats. Designed for rapid deployment in academic environments, the platform features automated face registration and localized caching to ensure fast loading times and immediate synchronization of student information.\n\n Made in 2025",img:"images/projects/FIST.webp",link:"https://github.com/IchimakiKasura/prototype-faceapi-code"},{title:"💖 RFID Powered School Database",sub:"School project | Web App with integrated Database and RFID | Node.js",desc:"The School Database Application with RFID is a robust desktop prototype built on the Electron.js framework, designed to streamline student data management through physical hardware integration. The system features a modern user interface crafted with HTML, CSS, and Less, providing a seamless experience while managing student identification via RFID technology. Primarily engineered for the SL040 Ver1.1 RFID reader, the application captures unique chip UIDs to automate entry logging and record-keeping within a localized environment. Additionally, the project includes a companion web portal for remote data access and is optimized for Node.js, offering a practical, ready-to-use solution for academic or small-scale institutional attendance requirements.\n\n Made in 2024",img:"images/projects/rfid.webp",link:"https://github.com/IchimakiKasura/prototype"},{title:"💖 Ceele Launcher",sub:"Wrapper | Desktop Application | C#",desc:"CeeleLauncher is a lightweight, open-source game launcher for HoYoverse titles that serves as a high-performance alternative to official software, maintaining an exceptionally small footprint of less than 5MB. Developed using .NET 7, the application features a modernized UI that prioritizes utility by including direct shortcuts for daily check-ins, interactive maps, and screenshot management while removing non-essential social media links. The project is now completely discontinued and no longer maintained following the release of the official HoyoPlay platform. Although it is no longer receiving updates, the source code remains publicly available under the MIT license for users interested in forking or archiving the legacy tool.\n\n Made in 2023",img:"images/projects/ceele.webp",link:"https://github.com/IchimakiKasura/CeeleLauncher"},{title:"💖 LauncherDL-3",sub:"Wrapper | Desktop Application | C#",desc:"Launcher DL 7.1 is a high-performance audio and video downloader GUI built on the .NET 7 framework, designed as a modern wrapper for the yt-dlp engine. This project serves as a functional platform for media extraction, evolving through multiple iterations from basic HTML designs to a structured C# environment to ensure peak efficiency. The current build focuses exclusively on yt-dlp compatibility to overcome the limitations of legacy tools, providing a streamlined interface for the latest streaming standards. While legacy versions (v1-v6) are no longer maintained, the latest stable release offers a complete, open-source solution for users and developers who have the .NET 7 SDK installed.\n\n Made in 2021",img:"images/projects/launcherdl.webp",link:"https://github.com/IchimakiKasura/Launcher-DL-3"},{title:"💖 IC-TAP",sub:"School project | Game Development | Adobe Animate",desc:"A Flappy Bird-inspired Android game created in Adobe Animate with an endless gameplay with a scaling difficulty. Made for school project performance task.\n\n Made in 2025",img:"images/projects/IC-TAP.webp",link:"downloadables/ICTAP.apk"},{title:"Erisu-Corner",sub:"Web Development",desc:"Another web development project to test my ability to design a website. The original website that was made from Wordpress and even the facebook page is no longer exist. This site will stay forever as my learning progress :>\n\n Made in 2021",img:"images/projects/erisu.webp",link:"https://ichimakikasura.github.io/erisu-corner-project/"},{title:"Trap Shop POS",sub:"School project | Web Development",desc:"My POS project is a web-based payment system prototype I developed for my school requirements, hosted directly via GitHub Pages. Built primarily with JavaScript, the application provides a functional interface for managing transactions and processing simulated online payments. I’ve structured the repository to include dedicated image assets and binary folders, ensuring the system is lightweight and easy to deploy for academic demonstrations. The project is open-source under the MIT license, serving as a practical example of front-end development for small-scale institutional use.\n\n Made in 2024",img:"images/projects/pos.webp",link:"https://ichimakikasura.github.io/pos"},{title:"💖 UCSP Peta Compilation",sub:"School project | Web Development",desc:"Designed and managed a web compilation portal for Grade-11 ICT students to host their UCSP Performance Tasks. The site organizes student-led blogs and video content into a single, mobile-responsive directory for easier grading and peer review.\n\n Made in 2023",img:"images/projects/ucsp.webp",link:"https://ichimakikasura.github.io/ICT/UCSP"},{title:"kasu.nhentaiapi.js",sub:"API Wrapper, Web Scraper | Node.js",desc:"A Node.js API wrapper that simplifies interaction with nhentai by providing an easy-to-use interface for users.\n\n Made in 2021",img:"images/projects/kasunhentai.webp",link:"https://github.com/IchimakiKasura/kasu.nhentaiapi.js"},{title:"Sosharumedia",sub:"Stack Development | XAMPP",desc:"A full stack website using XAMPP, created for the fun and learning. It's a social media platform. Likely stopped due to lack of security knowledge (XSS) as the site is built from ground up.\n\n Made in 2020",img:"images/projects/sosharu.webp",link:"https://github.com/IchimakiKasura/sosharumedia"},{title:"Boxy Quest",sub:"Game Development | Unity3D",desc:"A 2D adventure game featuring exploration, platforming, and puzzle-solving mechanics built as a personal game development project.\n\n Made in 2019",img:"images/projects/boxy.webp",link:"https://razinedge.itch.io/bqd"},{title:"3D Tank Trouble",sub:"Game Development | Unity3D",desc:"3D Tank Trouble Beta 3 is a stylized 3D action prototype heavily influenced by the TankTrouble maze-combat formula, retaining the signature top-down playstyle while modernizing the visual environment. The project preserves the core strategic loop of navigating structured mazes and utilizing bouncing projectiles to eliminate opponents, though it does not aim for a 1:1 functional replica of the original game's mechanics. Developed as a standalone desktop experience, the game leverages 3D environmental physics to enhance spatial awareness and trick-shot calculations within its narrow corridors.\n\n Made in 2017",img:"images/projects/3dtank.webp",link:"https://www.youtube.com/watch?v=ILb6QLAXqog"}],previewTitle=document.getElementById("p-title"),previewSubtitle=document.getElementById("p-desc"),previewImage=document.getElementById("p-img"),teachingImage=document.getElementById("teaching-image"),teachingCounter=document.getElementById("teaching-counter"),galleryButtons=document.querySelectorAll(".gallery-btn"),revealElements=document.querySelectorAll(".reveal"),teachingImages=Array.from({length:6},(e,t)=>`/images/workshop/${t+1}.webp`),loadedPreviewImages=new Set;let activeProjectIndex=null,teachingIndex=0,activePreviewRequest=0;function loadPreviewImage(e){if(!previewImage||!e)return;const t=++activePreviewRequest;if(previewImage.getAttribute("src")===e)return previewImage.dataset.loaded="true",void loadedPreviewImages.add(e);if(loadedPreviewImages.has(e))return previewImage.src=e,void(previewImage.dataset.loaded="true");previewImage.removeAttribute("src");const i=new Image;i.decoding="async",i.src=e,i.addEventListener("load",()=>{t===activePreviewRequest&&(previewImage.src=e,previewImage.dataset.loaded="true",loadedPreviewImages.add(e))},{once:!0})}const SOCIAL_LINKS={dc:"https://discord.com/users/1515722036209520940",gh:"https://github.com/IchimakiKasura",gm:"malto:ichimakikasura@gmail.com"};function createProject(e){const t=document.createElement("div"),i=document.createElement("h3"),a=document.createElement("span");t.classList.add("project-item"),i.innerText=data[e].title,a.innerText=data[e].sub,t.appendChild(i),t.appendChild(a);let n=0,o=0;const r=()=>{data[e].link&&window.open(data[e].link,"_blank","noopener,noreferrer")};return t.addEventListener("pointerdown",e=>{n=e.clientX,o=e.clientY}),t.addEventListener("click",t=>{t.preventDefault();const i=Math.abs(t.clientX-n),a=Math.abs(t.clientY-o);i>10||a>10||(window.innerWidth<=900?activeProjectIndex===e?r():(showProject(e),activeProjectIndex=e):(showProject(e),r()))}),t.addEventListener("pointerenter",()=>{window.innerWidth>900&&showProject(e)}),t}async function showProject(e){const t=new Image;t.src=data[e].img,await t.decode(),previewTitle.innerText=data[e].title,previewSubtitle.innerText=data[e].desc,previewImage.src=t.src,loadPreviewImage(data[e].img)}function updateTeachingImage(){teachingImage&&teachingCounter&&(teachingImage.src=teachingImages[teachingIndex],teachingImage.alt=`Teaching students ${teachingIndex+1}`,teachingCounter.textContent=`${teachingIndex+1} / ${teachingImages.length}`)}document.querySelectorAll("[data-social]").forEach(e=>{e.addEventListener("click",()=>{const t=e.dataset.social;t&&SOCIAL_LINKS[t]&&("gm"==t?window.location.href=SOCIAL_LINKS[t]:window.open(SOCIAL_LINKS[t]))})}),data.forEach((e,t)=>{const i=document.querySelector(".project-list"),a=createProject(t);i.appendChild(a)}),galleryButtons.forEach(e=>{e.addEventListener("click",()=>{const t="next"===e.dataset.direction?1:-1;teachingIndex=(teachingIndex+t+teachingImages.length)%teachingImages.length,updateTeachingImage()})});const revealObserver="IntersectionObserver"in window?new IntersectionObserver((e,t)=>{e.forEach(e=>{if(e.isIntersecting){const i=e.target,a=Number(i.dataset.delay??0);i.style.transitionDelay=`${a}s`,i.classList.add("is-visible"),t.unobserve(i)}})},{threshold:.16}):null;revealElements.forEach(e=>{revealObserver?revealObserver.observe(e):e.classList.add("is-visible")}),window.lenis=new Lenis({duration:1,lerp:.05,wheelMultiplier:.8,infinite:!1,smoothWheel:!0,anchors:!0,allowNestedScroll:!0,autoRaf:!0}),updateTeachingImage();